#!/bin/bash
# Generate the other harnesses' copies of what Pi owns.
# Usage: ./scripts/harness_sync.sh [--check]
#   (none)   rewrite the generated files
#   --check  exit non-zero when any generated file is out of date
#
# Pi's mcp.json is the source for OpenCode's and Codex's MCP servers; ./mcp_setup.sh install-claude imports it into Claude Code.
# Claude Code only loads mod files whose real path is inside the mod, so its mods get copies of Pi's shared TypeScript.

set -euo pipefail

DOTFILES_DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )/.." && pwd )"
STOW_DIR="$DOTFILES_DIR/stow"
PI_MCP="$STOW_DIR/pi/.pi/agent/mcp.json"
OPENCODE_CONFIG="$STOW_DIR/opencode/.config/opencode/opencode.jsonc"
CODEX_CONFIG="$STOW_DIR/codex/.codex/config.toml"
OPENCODE_BEGIN="    // BEGIN generated by scripts/harness_sync.sh from stow/pi/.pi/agent/mcp.json; edit that file instead."
OPENCODE_END="    // END generated MCP servers"
# The ChatGPT app installs and rewrites these Codex servers for its browser and computer use; every other Codex server comes from Pi.
CODEX_APP_SERVERS="node_repl computer-use"
# Pi path, then the Claude Code mod path that gets a copy.
SHARED_COPIES=(
    "pi/.pi/agent/extensions/jev-guardrails/shared.ts claude/.claude/mods/jev-checks/hooks/jev-shared.ts"
    "pi/.pi/agent/extensions/xai-search/xai-shared.ts claude/.claude/mods/xai-search/hooks/xai-shared.ts"
)

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

info() { echo -e "${GREEN}[sync]${NC} $1"; }
error() { echo -e "${RED}[sync]${NC} $1" >&2; exit 1; }

# OpenCode spells environment references {env:NAME} where Pi spells them ${NAME}.
opencode_servers() {
    jq '
        def opencode_env: with_entries(.value |= gsub("\\$\\{(?<name>[A-Za-z_][A-Za-z0-9_]*)\\}"; "{env:\(.name)}"));
        .mcpServers | with_entries(.value |= (
            . as $server
            | (if $server.url then {type: "remote", url: $server.url}
               else {type: "local", command: ([$server.command] + ($server.args // []))} end)
            + (if $server.headers then {headers: ($server.headers | opencode_env)} else {} end)
            + (if $server.env then {environment: ($server.env | opencode_env)} else {} end)
            + (if $server.enabled == false then {enabled: false} else {} end)
            + (if $server.exposure == "direct" then {codemode: false} elif $server.exposure == "codemode" then {codemode: true} else {} end)
            # Execution matches Pi'"'"'s per-request timeout (60 s unless set); stdio servers get longer to list tools because npx may install first.
            + {timeout: {catalog: (if $server.url then 10000 else 30000 end), execution: (($server.timeout // 60) * 1000)}}
        ))
    ' "$PI_MCP"
}

render_opencode() {
    local servers
    servers="$(opencode_servers | sed '1s/^/"servers": /' | sed 's/^/    /')"
    # BSD awk rejects newlines in -v values, so the block travels through the environment.
    SERVERS="$servers" awk -v begin="$OPENCODE_BEGIN" -v end="$OPENCODE_END" '
        $0 == begin { print; print ENVIRON["SERVERS"]; skipping = 1; found = 1; next }
        $0 == end { skipping = 0 }
        !skipping { print }
        END { if (!found) exit 2 }
    ' "$OPENCODE_CONFIG" || error "OpenCode config has no generated MCP markers: $OPENCODE_CONFIG"
}

# Codex reads secrets for headers and stdio servers by variable name, so each ${NAME} value must be the whole value.
codex_servers() {
    jq -r '
        # capture yields nothing on a miss, so collect it to get null for values that are not one whole reference.
        def whole_ref: [capture("^\\$\\{(?<name>[A-Za-z_][A-Za-z0-9_]*)\\}$")][0].name;
        def table($name; $object): if ($object | length) == 0 then empty else
            "", "[mcp_servers.\($name)]", ($object | to_entries[] | "\(.key) = \(.value | tojson)") end;
        .mcpServers | to_entries[] | .key as $name | .value as $server
        # jq 1.7 binds `a + b as $x` as `a + (b as $x | ...)`, so the whole sum is parenthesized.
        | ((if $server.url then {url: $server.url} else {command: $server.command, args: ($server.args // [])} end)
          + (if $server.enabled == false then {enabled: false} else {} end)
          + (if $server.timeout then {tool_timeout_sec: $server.timeout} else {} end)) as $main
        | ($server.headers // {} | to_entries) as $headers
        | ($server.env // {} | to_entries) as $env
        | if ($headers | map(select((.value | whole_ref) == null and (.value | test("\\$\\{")))) | length) > 0
             or ($env | map(select((.value | test("\\$\\{")) and (.value | whole_ref) != .key)) | length) > 0
          then error("\($name): Codex can only pass a whole ${NAME} value, and stdio env must reuse the same name")
          else
            ($main + (if ($env | map(select(.value | whole_ref)) | length) > 0 then {env_vars: [$env[] | select(.value | whole_ref) | .key]} else {} end)) as $main
            | table($name; $main),
              table("\($name).env_http_headers"; [$headers[] | select(.value | whole_ref) | {key, value: (.value | whole_ref)}] | from_entries),
              table("\($name).http_headers"; [$headers[] | select((.value | whole_ref) == null)] | from_entries),
              table("\($name).env"; [$env[] | select((.value | test("\\$\\{")) | not)] | from_entries)
          end
    ' "$PI_MCP"
}

render_codex() {
    local servers
    servers="$(codex_servers | sed '1{/^$/d;}')"
    SERVERS="$servers" awk -v keep="$CODEX_APP_SERVERS" '
        BEGIN { servers = ENVIRON["SERVERS"]; split(keep, names, " "); for (i in names) kept[names[i]] = 1 }
        function server_of(header,   name) {
            name = header
            sub(/^\[mcp_servers\./, "", name)
            sub(/[.\]].*$/, "", name)
            return name
        }
        /^\[/ {
            owned = ($0 ~ /^\[mcp_servers\./) && !(server_of($0) in kept)
            if (owned && !placed) { printf "%s", pending; pending = ""; print servers; print ""; placed = 1 }
        }
        owned { pending = ""; next }
        /^$/ { pending = pending "\n"; next }
        { printf "%s", pending; pending = ""; print }
        END { if (!placed) { print ""; print servers } }
    ' "$CODEX_CONFIG"
}

render_copy() {
    local source=$1
    printf '// Generated by scripts/harness_sync.sh from stow/%s; edit that file instead.\n' "$source"
    cat "$STOW_DIR/$source"
}

# Writes or checks one generated file; prints its path when it is stale.
apply() {
    local mode=$1 target=$2 rendered=$3
    if cmp -s "$rendered" "$target"; then
        return 0
    fi
    if [ "$mode" = check ]; then
        echo "${target#"$DOTFILES_DIR"/}"
        return 1
    fi
    cp "$rendered" "$target"
    info "wrote ${target#"$DOTFILES_DIR"/}"
}

main() {
    local mode=write stale=0 tmp pair source target
    case "${1:-}" in
        "") ;;
        --check) mode=check ;;
        *) error "Usage: $0 [--check]" ;;
    esac
    command -v jq &> /dev/null || error "jq is required"
    tmp="$(mktemp -d)"
    # The trap runs after main returns, when its locals are gone, so it gets the path expanded now.
    trap "rm -rf '$tmp'" EXIT

    render_opencode > "$tmp/opencode.jsonc"
    apply "$mode" "$OPENCODE_CONFIG" "$tmp/opencode.jsonc" || stale=1
    render_codex > "$tmp/config.toml"
    apply "$mode" "$CODEX_CONFIG" "$tmp/config.toml" || stale=1
    for pair in "${SHARED_COPIES[@]}"; do
        read -r source target <<< "$pair"
        render_copy "$source" > "$tmp/copy"
        # A stale symlink here would be followed by cp, so replace it with a real file.
        [ -L "$STOW_DIR/$target" ] && [ "$mode" = write ] && rm "$STOW_DIR/$target"
        apply "$mode" "$STOW_DIR/$target" "$tmp/copy" || stale=1
    done

    if [ "$stale" -ne 0 ]; then
        error "generated harness files are stale; run ./scripts/harness_sync.sh"
    fi
    [ "$mode" = check ] && info "generated harness files are up to date"
    return 0
}

main "$@"
